-- ─────────────────────────────────────────────────────────
--  One-time setup for the admin panel.
--  Paste this whole file into Supabase → SQL Editor → Run.
--  Safe to re-run: it won't duplicate or overwrite products.
-- ─────────────────────────────────────────────────────────

-- 1. Order status (used by /admin)
alter table orders add column if not exists status text not null default 'new';

-- 2. Products table (edited from /admin/products)
create table if not exists products (
  id          bigint generated by default as identity primary key,
  brand       text    not null,
  name        text    not null,
  category    text    not null,
  type        text    not null check (type in ('tintable', 'readymix', 'clear')),
  image       text    not null default '',
  description text    not null default '',
  bases       jsonb,  -- tintable:  [{ id, name, desc, packs: [{ size, mrp, price }] }]
  colors      jsonb,  -- readymix:  [{ id, name, hex }]
  packs       jsonb,  -- readymix / clear: [{ size, mrp, price }]
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- Only the server (service-role key) may read/write products.
-- RLS on + no policies = the public anon key gets nothing.
alter table products enable row level security;

-- 3. Storage bucket for product photos (public read, images up to 4 MB only)
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('product-images', 'product-images', true, 4194304, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update set
  file_size_limit    = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

